/**
 * Audit Log Middleware — Logs every admin action for accountability.
 * Generated by BackendForge
 */

const { AuditLog } = require('../models');

/**
 * Create an audit log middleware for a specific action.
 * @param {string} action - Description of the action (e.g., 'UPDATE_ORDER_STATUS')
 * @param {function} getDetails - (req) => { targetModel, targetId, changes }
 */
const auditLog = (action, getDetails) => {
  return async (req, res, next) => {
    // Store original json method to capture response
    const originalJson = res.json.bind(res);

    res.json = async function (data) {
      // Only log successful admin actions
      if (req.user && ['admin', 'superadmin'].includes(req.user.role) && res.statusCode < 400) {
        try {
          const details = getDetails ? getDetails(req, data) : {};
          await AuditLog.create({
            adminId: req.user.id || req.user._id,
            adminEmail: req.user.email,
            action,
            targetModel: details.targetModel || null,
            targetId: details.targetId || req.params.id || null,
            changes: details.changes || null,
            ip: req.ip || req.connection?.remoteAddress,
            userAgent: req.headers['user-agent'],
            metadata: { requestId: req.requestId, method: req.method, path: req.originalUrl },
          });
        } catch (err) {
          console.error('Audit log failed:', err.message);
          // Don't block the response if audit logging fails
        }
      }
      return originalJson(data);
    };

    next();
  };
};

/**
 * Log an audit action directly (not as middleware).
 */
const logAuditAction = async (adminUser, action, details = {}) => {
  try {
    await AuditLog.create({
      adminId: adminUser.id || adminUser._id,
      adminEmail: adminUser.email,
      action,
      targetModel: details.targetModel || null,
      targetId: details.targetId || null,
      changes: details.changes || null,
      ip: details.ip || null,
      userAgent: details.userAgent || null,
      metadata: details.metadata || {},
    });
  } catch (err) {
    console.error('Audit log failed:', err.message);
  }
};

module.exports = { auditLog, logAuditAction };
